(43, 3, 'ja', 'Order Detail', '<p>こんにちは、</ p> <p>親愛なる{owner_name}。</ p> <p>これは、<span style = \\\"font-size：1rem;\\\"> {order_date}の確認注文{order_id}の場所です。 </ span> </ p> <p>ありがとうございます</ p> <p> {order_url} </ p>', '2025-09-11 21:18:46', '2025-09-11 21:18:46'),
